#!/usr/bin/env bash\nset -euo pipefail\n\n# Force RANDOM to a known value so the emoji is predictable (index 2 => ✨)\nRANDOM=2\n\nPR_TITLE=\"Add new feature for user login\"\nLABEL_MAP='{"feature":"enhancement","bug":"bug"}'\n\noutput=$(./src/labeler.sh \"$PR_TITLE\" \"$LABEL_MAP\")\nexpected=$'enhancement\n✨'\n\nif [[ \"$output\" == \"$expected\" ]]; then\n  echo \"PASS\"\n  exit 0\nelse\n  echo \"FAIL\"\n  echo \"Got:\n$output\"\n  echo \"Expected:\n$expected\"\n  exit 1\nfi\n
